const $=s=>document.querySelector(s);
const settingsSvg=settingsNodes.map(([tag,attrs])=>`<${tag} ${Object.entries(attrs).filter(([key])=>key!=='key').map(([key,value])=>`${key}="${value}"`).join(' ')} />`).join('');
const paths={settings:settingsSvg,'panel-left':'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M9 3v18"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 6 6 6-6 6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',search:'<circle cx="10.8" cy="10.8" r="7"/><path d="m16 16 4.5 4.5"/>','arrow-up':'<path d="M12 19V5m-6 6 6-6 6 6"/>',sliders:'<path d="M4 7h8m4 0h4M4 17h3m4 0h9"/><circle cx="14" cy="7" r="2"/><circle cx="9" cy="17" r="2"/>',rules:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',memory:'<path d="M6 3h12v18l-6-4-6 4z"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.settings}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const materials=new Map();
function disposeWithin(root){for(const [host,api] of materials){if(root.contains(host)){api.destroy();materials.delete(host);}}}
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);el.removeAttribute('data-icon');});root.querySelectorAll('.material').forEach(el=>{if(!materials.has(el))materials.set(el,mountGlass(el,{preset:'button',radius:16,theme:'light',lightAngle:225,reflection:1}));});}
const records=[
 {id:1,kind:'rules',content:'教案先列教学目标，再列教学过程；课堂活动给出具体的教师提问。',status:'active',updated:'今天',source:'本人添加',expiry:''},
 {id:2,kind:'rules',content:'回答尽量简洁，用中文说明；不确定的学生情况先查记录。',status:'active',updated:'昨天',source:'本人添加',expiry:''},
 {id:3,kind:'rules',content:'课堂建议优先考虑四十分钟内能够完成的安排。',status:'disabled',updated:'10月25日',source:'本人添加',expiry:''},
 {id:4,kind:'memory',content:'这学期想重点改善课堂讨论的参与度。',status:'active',updated:'今天',source:'课堂讨论怎么组织 · 今天',expiry:''},
 {id:5,kind:'memory',content:'备课时习惯先整理单元目标，再安排每节课的活动。',status:'active',updated:'昨天',source:'备课思路 · 昨天',expiry:''},
 {id:6,kind:'memory',content:'希望每周留出一次课后反思的时间。',status:'active',updated:'10月25日',source:'本人添加',expiry:''},
 {id:7,kind:'memory',content:'今后的课堂讨论，优先尝试先独立思考、再小组交流。',status:'candidate',updated:'今天',source:'课堂讨论怎么组织 · 今天',expiry:''},
 {id:8,kind:'memory',content:'希望教案中的课堂活动附上预计用时。',status:'candidate',updated:'昨天',source:'七年级的备课思路 · 昨天',expiry:''},
];
let settingsArea='conversation';
let generationDraft={custom:false,temperature:0.7};
let section='rules',memoryFilter='work',query='',current=null,initial='',initialExpiry='',toastTimer,confirmAction;
let metrics={human:70,auto:90,score:75};
const content=$('#settings-content');
const button=(id,label,primary=false)=>`<button id="${id}" class="material ${primary?'primary':''}" type="button"><span class="lg-content">${label}</span></button>`;
function heading(title,description,action=''){return `<header class="page-heading"><div><span class="eyebrow">${settingsArea==='general'?'教学业务设置':'AI 助手'}</span><h2>${title}</h2><p>${description}</p></div>${action}</header>`;}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3200);}
function renderLinks(){const data=settingsArea==='general'?[['metrics','sliders','OCR 与评分']]:[['rules','rules','工作方式'],['memory','memory','记忆与事项'],['capabilities','sliders','模型与运行']];$('.settings-nav h1').textContent=settingsArea==='general'?'主设置':'会话设置';$('.settings-nav>.nav-caption').textContent=settingsArea==='general'?'青松教师':'AI 助手';$('.nav-note').innerHTML=settingsArea==='general'?'教学业务设置<br>此处仅演示 OCR 与评分':'个人规则与背景跨会话生效<br>生成参数可仅用于当前会话';$('#settings-links').innerHTML=data.map(([id,i,label])=>`<button class="settings-link" data-section="${id}" ${section===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('');$('#settings-links').querySelectorAll('button').forEach(b=>b.onclick=()=>{section=b.dataset.section;query='';renderSettings();});}
function rows(){const selected=records.filter(r=>r.kind===section&&r.status!=='deleted'&&(section!=='memory'||(memoryFilter==='pending'?r.status==='candidate':r.status!=='candidate'))&&r.content.includes(query));return selected.length?selected.map(r=>`<button class="record-row" data-record="${r.id}" aria-label="查看${esc(r.content)}"><span class="row-copy"><span class="row-title">${esc(r.content)}</span><span class="row-subtitle"><span class="row-status ${r.status==='candidate'?'pending':''}">${{active:'已启用',disabled:'已停用',candidate:'待确认'}[r.status]}</span><span>${r.updated}${r.source==='本人添加'?' · 本人添加':''}</span></span></span>${icon('chevron')}</button>`).join(''):'<p class="empty">没有符合条件的记录。</p>';}
function wireRows(){content.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>openEntry(records.find(r=>r.id===Number(b.dataset.record))));}
function renderSettings(){disposeWithin(content);renderLinks();if(section==='metrics')renderMetrics();else if(section==='capabilities')renderCapabilities();else if(section==='memory'&&memoryFilter==='work')renderWork();else if(section==='rules'){
 content.innerHTML=heading('工作方式','你的个人规则，以及助手遵循的方法。',button('new-entry',icon('plus')+'新增',true))+`<div class="row-list">${rows()}</div><p class="footnote">个人规则用于你的后续对话。当前明确要求优先；不会改变系统权限。</p><details class="disclosure"><summary>行为原则与处理方法</summary><p>身份与职责：协助教师查询记录、整理工作和形成建议。</p><p>先核对对象和依据，说明不确定性。业务成功以回执为准，不能靠聊天或旧记忆推断。</p><p>方法与技能：字段定位、工具使用和处理流程由系统维护。这里披露结构，未修改真实提示词或 Skill。</p><small>来源：系统设计 · 教师个人规则不能覆盖这些权限边界</small></details>`;$('#new-entry').onclick=()=>openEntry(null);
 }else{
 const count=records.filter(r=>r.kind==='memory'&&r.status==='candidate').length;
 content.innerHTML=heading('记忆与事项','未完的工作与长期背景，分别保存。',button('new-entry',icon('plus')+'新增',true))+(count&&memoryFilter==='saved'?`<div class="review-line"><span>${count} 条记忆待你确认</span><button id="review-pending">去查看 ${icon('chevron')}</button></div>`:'')+`<div class="memory-tools"><div class="segment-wrap"><div id="memory-segments"><button data-value="work">协作事项</button><button data-value="saved">长期背景</button><button data-value="pending">待确认${count?' · '+count:''}</button></div></div><label class="search">${icon('search')}<input id="search-memory" type="search" aria-label="搜索记忆" placeholder="搜索记忆" value="${esc(query)}"></label></div><div class="row-list" id="memory-list">${rows()}</div><p class="footnote">只保留你希望助手记住的内容。未确认的建议不会作为记忆使用。</p>`;
 const host=$('#memory-segments');materials.set(host,mountSegmented(host,{value:memoryFilter,trackRim:false,liftPx:2,glass:{theme:'light',lightAngle:225,reflection:1},onChange:value=>{memoryFilter=value;query='';renderSettings();}}));
 $('#new-entry').onclick=()=>openEntry(null);if($('#review-pending'))$('#review-pending').onclick=()=>{memoryFilter='pending';renderSettings();};
 $('#search-memory').oninput=e=>{query=e.target.value;$('#memory-list').innerHTML=rows();wireRows();};
 }hydrate(content);wireRows();if(section==='capabilities')wireGeneration();}
function control(key,title,value,min,max,step=1){return `<div class="metric-control ${key==='score'?'solo':''}"><label for="metric-${key}">${title}<output id="output-${key}" for="metric-${key}">${value}<small>%</small></output></label><input id="metric-${key}" type="range" value="${value}" min="${min}" max="${max}" step="${step}"></div>`;}
function renderMetrics(){content.innerHTML=heading('OCR 与评分','保留识别质量和评分置信度的调节入口。')+`<section class="metric-group"><h3>图像与 OCR 质检</h3><p>调整识别质量的参考阈值。</p><div class="metric-controls">${control('human','人工复核阈值',metrics.human,50,80,5)}${control('auto','自动通过阈值',metrics.auto,75,98)}</div></section><section class="metric-group"><h3>AI 评分置信度</h3><p>查看评分结果时使用的置信度参考。</p><div class="metric-controls">${control('score','评分置信度阈值',metrics.score,50,95,5)}</div></section><div class="metric-actions">${button('save-metrics','保存设置',true)}</div><p class="footnote">当前正式页面使用固定默认值；这些调节尚未完整接通判定流程。此处只模拟保存，不改变真实批改。</p><details class="disclosure"><summary>指标含义与生效范围</summary><p>人工复核与自动通过阈值：拟用于 OCR 质量分流，需先验证质量分数的定义及其与真实错误的关系。</p><p>评分置信度阈值：拟用于标记需教师核对的结果；不应将模型自评直接当作准确率。</p><p>正式接入前需确定参数存储、对哪些新任务生效，以及判定服务的实际消费位置。未接入前不显示“全局已生效”。</p></details>`;
 for(const key of ['human','auto','score'])$('#metric-'+key).oninput=e=>{let value=Number(e.target.value);if(key==='human')value=Math.min(value,Number($('#metric-auto').value)-5);if(key==='auto')value=Math.max(value,Number($('#metric-human').value)+5);e.target.value=value;$('#output-'+key).innerHTML=value+'<small>%</small>';};
 $('#save-metrics').onclick=()=>{for(const key of ['human','auto','score'])metrics[key]=Number($('#metric-'+key).value);toast('演示：阈值已保存，未改变真实批改设置。');};}
function confirm(title,body,action,label='确认'){$('#confirm-title').textContent=title;$('#confirm-body').textContent=body;$('#confirm-yes .lg-content').textContent=label;confirmAction=action;$('#confirm-dialog').showModal();}
function dirty(){return $('#entry-content').value!==initial||$('#entry-expiry').value!==initialExpiry;}
function closeEntry(){if(dirty())confirm('放弃未保存的修改？','本次填写尚未保存。',()=>$('#entry-dialog').close(),'放弃修改');else $('#entry-dialog').close();}
function openEntry(record){current=record;initial=record?.content??'';initialExpiry=record?.expiry??'';const kind=record?.kind??section;const pending=record?.status==='candidate';$('#dialog-category').textContent=kind==='rules'?'个人规则':'长期记忆';$('#dialog-title').textContent=pending?'确认这条记忆':record?'编辑内容':kind==='rules'?'新增个人规则':'新增记忆';$('#content-label').textContent=pending?'拟保存的内容':'内容';$('#entry-content').value=initial;$('#entry-content').placeholder=kind==='rules'?'例如：教案先列教学目标，再列教学过程。':'例如：这学期重点改善课堂讨论参与度。';$('#entry-expiry').value=initialExpiry;$('#entry-meta').textContent=pending?'确认前，你可以先调整这段内容。':record?'当前'+(record.status==='active'?'已启用':'已停用')+' · 更新于'+record.updated:'保存后用于后续助手请求。';$('#entry-source').textContent='来源：'+(record?.source??'本人添加');$('#save-entry .lg-content').textContent=pending?'确认保存':record?'保存修改':'保存';$('#more-entry').hidden=!record;$('#more-menu').hidden=true;$('#more-entry').setAttribute('aria-expanded','false');$('#toggle-entry').textContent=pending?'暂不保存':record?.status==='disabled'?'启用这条记录':'停用这条记录';$('#history-panel').hidden=true;$('#entry-dialog').querySelector('details').open=pending;$('#entry-dialog').showModal();hydrate($('#entry-dialog'));}
$('#entry-form').onsubmit=e=>{e.preventDefault();const text=$('#entry-content').value.trim();if(!text){$('#entry-content').focus();return;}const pending=current?.status==='candidate';if(current){current.content=text;current.expiry=$('#entry-expiry').value;current.updated='刚刚';if(pending)current.status='active';}else records.push({id:Date.now(),kind:section,content:text,expiry:$('#entry-expiry').value,status:'active',updated:'刚刚',source:'本人添加'});$('#entry-dialog').close();renderSettings();toast(pending?'演示：记忆已确认保存。':'演示：已保存，未改动真实记录。');};
$('#close-entry').onclick=closeEntry;$('#entry-dialog').oncancel=e=>{e.preventDefault();closeEntry();};
$('#more-entry').onclick=()=>{$('#more-menu').hidden=!$('#more-menu').hidden;$('#more-entry').setAttribute('aria-expanded',String(!$('#more-menu').hidden));};
$('#history-entry').onclick=()=>{$('#history-panel').hidden=false;$('#history-panel').textContent='修改记录示例：今天保存当前内容。实际应用中将在这里查看历史版本和原始来源。';$('#more-menu').hidden=true;};
$('#toggle-entry').onclick=()=>{if(dirty()){toast('请先保存或取消当前修改。');return;}if(current.status==='candidate'){confirm('暂不保存这条记忆？','这条建议不会作为长期记忆使用。',()=>{current.status='deleted';$('#entry-dialog').close();renderSettings();toast('演示：已忽略这条建议。');},'暂不保存');return;}current.status=current.status==='active'?'disabled':'active';$('#entry-dialog').close();renderSettings();toast('演示：已'+(current.status==='active'?'启用':'停用')+'。');};
$('#delete-entry').onclick=()=>confirm('删除这条记录？','后续不再召回这条内容，原对话和历史版本仍保留。',()=>{current.status='deleted';$('#entry-dialog').close();renderSettings();toast('演示：记录已删除。');},'删除');
$('#confirm-cancel').onclick=()=>$('#confirm-dialog').close();$('#confirm-yes').onclick=()=>{$('#confirm-dialog').close();confirmAction?.();};
function scene(name){const chat=name==='chat';if(!chat){generationDraft={...(activeDemo().generation??{custom:false,temperature:0.7})};settingsArea=name==='general'?'general':'conversation';if(settingsArea==='general')section='metrics';else if(section==='metrics')section='rules';renderSettings();}$('#settings-scene').hidden=chat;$('#chat-scene').hidden=!chat;$('#breadcrumb').textContent=chat?'工作台 / AI 助手':settingsArea==='general'?'主设置 / OCR 与评分':'AI 助手 / 会话设置';$('#return-chat').hidden=chat;document.querySelectorAll('[data-scene]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scene===name)));}
document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>scene(b.dataset.scene));$('#return-chat').onclick=()=>scene('chat');$('#sidebar-settings').onclick=()=>{section='rules';renderSettings();scene('settings');};
function collapse(value){$('#chat-sidebar').hidden=value;$('#expand-sidebar').hidden=!value;$('#chat-scene').classList.toggle('sidebar-collapsed',value);}
$('#collapse-sidebar').onclick=()=>collapse(true);$('#expand-sidebar').onclick=()=>collapse(false);
$('#phone-toggle').onclick=()=>{const enabled=$('#preview').classList.toggle('phone');$('#phone-toggle').setAttribute('aria-pressed',String(enabled));document.body.dataset.phone=String(enabled);};
$('#send-demo').onclick=sendDemo;
$('.new-chat .lg-content').innerHTML=icon('plus')+'新对话';

function generationControls(){return `<section class="generation-controls"><div class="generation-title"><h3>温度 <span>Temperature</span></h3><span class="status-pill">当前会话 · 演示</span></div><p>较低时采样更集中；较高时回答变化更大。温度不代表准确率。</p><label class="inherit-control"><input id="inherit-temperature" type="checkbox" ${generationDraft.custom?'':'checked'}>跟随模型默认值</label><div id="temperature-custom" ${generationDraft.custom?'':'hidden'}><label for="temperature-value">自定义温度 <output id="temperature-output">${generationDraft.temperature.toFixed(1)}</output></label><input id="temperature-value" type="range" min="0" max="2" step="0.1" value="${generationDraft.temperature}"><div class="range-captions"><span>采样集中</span><span>变化更多</span></div></div><p class="footnote">默认值未在这里假定。0–2 仅为原型演示范围；正式控件按具体模型能力调整，不支持时说明原因。</p><div class="operation-actions">${button('save-generation','保存会话设置',true)}</div><p id="generation-feedback" role="status" class="footnote"></p></section>`;}
function wireGeneration(){$('#inherit-temperature').onchange=e=>{generationDraft.custom=!e.target.checked;$('#temperature-custom').hidden=!generationDraft.custom;$('#generation-feedback').textContent='尚未保存的演示设置';};$('#temperature-value').oninput=e=>{generationDraft.temperature=Number(e.target.value);$('#temperature-output').textContent=generationDraft.temperature.toFixed(1);$('#generation-feedback').textContent='尚未保存的演示设置';};$('#save-generation').onclick=()=>{activeDemo().generation={...generationDraft};$('#generation-feedback').textContent=generationDraft.custom?'演示：当前会话从下一条新请求使用温度 '+generationDraft.temperature.toFixed(1)+'；已有消息不变。':'演示：当前会话跟随模型默认温度。';toast('仅保存演示设置，未改变真实模型调用。');};}

// All records and transitions below are local simulations, never teaching tools.
const workItems=[
 {id:'follow',title:'跟进小林的作业补交',state:'待核对',detail:'上次约定：周五核对补交情况，再决定是否安排课后沟通。',next:'重新读取课堂任务，确认当前结果。',source:'10 月 26 日 · 作业跟进',ref:'七年级一班 · 周三阅读检查'},
 {id:'discussion',title:'调整下周课堂讨论',state:'待补充',detail:'已选“先独立思考，再小组交流”，尚未确定课文与分组方式。',next:'确认课文及课堂时长。',source:'昨天 · 课堂讨论怎么组织',ref:'教学方案草稿 · 尚未写入日程'},
];
let selectedWork=null;
function memorySegments(){return `<div class="memory-tabs" role="group" aria-label="记忆分类">${[['work','协作事项'],['saved','长期背景'],['pending','待确认']].map(([key,label])=>`<button data-memory-tab="${key}" aria-pressed="${memoryFilter===key}">${label}</button>`).join('')}</div>`;}
function wireMemoryTabs(){content.querySelectorAll('[data-memory-tab]').forEach(b=>b.onclick=()=>{memoryFilter=b.dataset.memoryTab;selectedWork=null;renderSettings();});}
function renderWork(){content.innerHTML=heading('记忆与事项','继续未完的工作，查看已经确认的背景。')+memorySegments()+(selectedWork?`<section class="work-detail"><button id="back-work" class="text-button">‹ 返回事项</button><span class="status-pill">${selectedWork.state}</span><h3>${selectedWork.title}</h3><p>${selectedWork.detail}</p><dl><dt>关联记录</dt><dd>${selectedWork.ref}</dd><dt>上次约定</dt><dd>${selectedWork.next}</dd><dt>来源</dt><dd>${selectedWork.source}</dd></dl>${button('resume-work','继续这件事',true)}<p class="footnote">继续时重新查询当前业务记录。旧约定不会直接触发写入。</p></section>`:`<div class="row-list">${workItems.map(w=>`<button class="record-row" data-work="${w.id}"><span class="row-copy"><span class="row-title">${w.title}</span><span class="row-subtitle"><span class="row-status">${w.state}</span><span>${w.source}</span></span><span class="work-next">${w.next}</span></span>${icon('chevron')}</button>`).join('')}</div><p class="footnote">事项保存目标、约定和下一步。学生结果、任务进度仍以业务记录为准。</p>`);wireMemoryTabs();content.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>{selectedWork=workItems.find(w=>w.id===b.dataset.work);renderSettings();});if($('#back-work'))$('#back-work').onclick=()=>{selectedWork=null;renderSettings();};if($('#resume-work'))$('#resume-work').onclick=()=>{const follow=selectedWork.id==='follow';scene('chat');switchDemo(follow?'follow':'discussion',true);collapse(true);if(follow){$('#chat-draft').value='继续跟进小林的作业补交，先核对现在的记录。';demoSessions.follow.draft=$('#chat-draft').value;}else{$('#chat-draft').value='继续讨论方案，先确定课文和分组方式。';demoSessions.discussion.draft=$('#chat-draft').value;}$('#chat-draft').focus();};}
function renderCapabilities(){content.innerHTML=heading('模型与运行','调整当前会话的生成方式，了解能力与运行边界。')+generationControls()+`<section class="capability-block"><h3>可访问的教学信息</h3><p>班级与名单、课表、课堂任务、座位、提醒及部分学生记录。</p><details class="disclosure"><summary>查看权限与尚未开放的能力</summary><p>学生主体及身份由教师手动维护。资料检索、批改结果与业务写入尚未接入正式助手。</p><p>课堂结果写入、动态字段更新、跨会话事项属于本次设计目标。原型里的成功状态不代表已上线。</p></details></section><section class="capability-block"><h3>模型与生成参数</h3><p>模型参数决定生成方式，OCR 与评分阈值决定业务处理参考，两者分别配置。</p><dl class="parameter-list"><dt>Temperature</dt><dd>控制采样随机性。上方可模拟选择跟随模型或为当前会话自定义。</dd><dt>输出长度</dt><dd>正式助手目前每次请求最多 2,048 Token；原型只披露，不修改。</dd><dt>推理强度</dt><dd>按模型支持范围提供；不能保证所有模型均可调整。</dd></dl><details class="disclosure"><summary>其他参数与生效范围</summary><p>top_p、惩罚系数、stop 等不能仅因接口名称常见就提供开关。需逐项核对实际调用链，未接通时不显示可保存的控件。</p><p>温度在原型中按当前会话展示；个人规则和长期背景按本人跨会话使用。模型供应商、身份权限与全局预算由系统管理。</p></details></section><section class="capability-block"><h3>运行与上下文</h3><dl class="parameter-list"><dt>处理预算</dt><dd>目前每轮最多 8 步、12 次工具调用、180 秒。</dd><dt>排队</dt><dd>目前全局 1 条执行，最多 3 条等待。等待不代表模型已经开始生成。</dd><dt>记忆使用</dt><dd>加载有效个人规则并有限召回；工作事项与可靠续办是待实现目标。</dd></dl><details class="disclosure"><summary>查看上下文组成</summary><p>系统职责与权限 → 当前请求 → 经核对的工作状态与业务证据 → 相关个人背景。字段与工具方法由 Skill/契约描述。</p><p>压缩保留目标、未决问题、对象与操作引用，不把摘要作为写入回执。此处是目标结构，尚未改变运行时。</p></details></section>`;}

const demoSessions={
 classroom:{title:'本周的课堂记录',loaded:true,draft:'把阅读检查中小林和小周的结果记为已完成。',status:'',messages:[{role:'assistant',text:'可以先核对这次阅读检查，再预览具体修改。所有姓名与记录都是演示数据。'}]},
 follow:{title:'作业补交跟进',loaded:false,draft:'',status:'',messages:[]},
 discussion:{title:'课堂讨论怎么组织',loaded:true,draft:'',status:'',messages:[{role:'user',text:'下次讨论先独立思考，再分组交流。'},{role:'assistant',text:'先保留这个方案。接下来需要确定课文和分组方式，尚未安排实际日程。'}]},
};
let demoActive='classroom',demoMode='normal',localSequence=0;
const demoTimers=new Set();
function later(fn,delay){const timer=setTimeout(()=>{demoTimers.delete(timer);fn();},delay);demoTimers.add(timer);return timer;}
function activeDemo(){return demoSessions[demoActive];}
function updateDemo(key){if(demoActive===key)renderDemo();}
function renderDemo(){const session=activeDemo(),reading=$('.chat-reading');const sameSession=reading.dataset.session===demoActive;const previousScroll=reading.scrollTop;const nearBottom=reading.scrollHeight-reading.clientHeight-previousScroll<70;reading.dataset.session=demoActive;disposeWithin(reading);$('#demo-session-title').textContent=session.title;$('#demo-history-status').textContent=session.historyStatus||'';$('#demo-history-status').hidden=!session.historyStatus;$('.chat-reading').innerHTML=session.loaded?session.messages.map((m,i)=>m.role==='user'?`<div class="message-group"><p class="user-message">${esc(m.text)}</p>${m.status?`<p class="submission-status" role="status">${esc(m.status)}</p>`:''}</div>`:`<article class="answer"><span class="assistant-mark">青松 · 演示</span>${m.text?`<p>${esc(m.text)}</p>`:''}${m.phase?renderOperation(m,i):''}</article>`).join(''):`<div class="history-placeholder" role="status"><span class="loading-dot"></span><p>正在读取「${esc(session.title)}」的历史</p><small>不会把其他会话的内容显示在这里。</small></div>`;$('#chat-draft').value=session.draft;$('#chat-draft').disabled=!session.loaded;$('#send-demo').disabled=!session.loaded||Boolean(session.busy);$('#demo-composer-status').textContent=session.status||'仅演示，不发送真实请求';$('#demo-conversations').innerHTML=Object.entries(demoSessions).map(([key,value])=>`<button data-demo-session="${key}" class="${key===demoActive?'selected':''}" aria-current="${key===demoActive?'page':'false'}">${value.title}${value.busy?' · 处理中':''}</button>`).join('');$('#demo-conversations').querySelectorAll('button').forEach(b=>b.onclick=()=>switchDemo(b.dataset.demoSession,true));$('.chat-reading').querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>operateDemo(b.dataset.op,Number(b.dataset.index)));hydrate(reading);reading.scrollTop=!sameSession||nearBottom?reading.scrollHeight:previousScroll;}
function renderOperation(message,index){const act=(action,label,primary=false)=>`<button type="button" class="material ${primary?'primary':''}" data-op="${action}" data-index="${index}"><span class="lg-content">${label}</span></button>`;const phase=message.phase;return `<section class="operation-card"><span class="status-pill">${{preview:'待确认',executing:'正在提交',done:'已核对提交结果',unknown:'结果待核对',checking:'正在核对',conflict:'记录已变化',cancelled:'已取消'}[phase]}</span><h3>七年级一班 · 阅读检查</h3>${phase==='preview'?`<p>小林、小周：未记录 → 已完成</p><p class="operation-meta">仅这两名学生 · 不修改学生档案</p><details><summary>查看依据与范围</summary><p>演示任务 T-1028；成员版本 3、7；当前无已记录结果。正式执行需重新校验版本与权限。</p></details><div class="operation-actions">${act('cancel','取消')}${act('confirm','确认这次记录',true)}</div>`:phase==='conflict'?`<p>小周的结果已由其他操作更新。本次没有提交，也不会覆盖新记录。</p><div class="operation-actions">${act('refresh','查看最新记录',true)}</div>`:phase==='unknown'?`<p>连接中断，尚不能确认是否保存。保留原操作编号，先核对结果，避免重复记录。</p><p class="operation-meta">演示操作 ${esc(message.operationId)}</p><div class="operation-actions">${act('reconcile','核对原操作',true)}</div>`:phase==='done'?`<p>演示回执：小林、小周的本次结果已记录。</p><dl><dt>操作编号</dt><dd>${esc(message.operationId)}</dd><dt>结果依据</dt><dd>原操作回执 · 2 条事件</dd></dl><p class="operation-meta">这是一份模拟回执，真实课堂数据未修改。</p>`:phase==='cancelled'?'<p>本次未提交，原记录保持原状。</p>':`<p role="status"><span class="loading-dot"></span>${phase==='checking'?'按原操作编号查询提交结果…':'正在提交这两名学生的记录…'}</p>`}</section>`;}
function switchDemo(key,refresh){const old=activeDemo();old.draft=$('#chat-draft').value;demoActive=key;const session=activeDemo();if(!refresh){renderDemo();return;}if(session.historyTimer){clearTimeout(session.historyTimer);demoTimers.delete(session.historyTimer);}session.historyStatus=session.loaded?'已显示此会话的本地内容，正在核对最新记录…':'正在读取历史…';renderDemo();if(matchMedia('(max-width:700px)').matches||$('#preview').classList.contains('phone'))collapse(true);session.historyTimer=later(()=>{session.historyTimer=null;if(!session.loaded){session.loaded=true;session.messages=[{role:'user',text:'周五再看小林是否补交，先不要公开点名。'},{role:'assistant',text:'上次约定是周五核对补交情况，再决定下一步。现在继续时会先读取最新课堂记录；旧约定不代表已经补交。'}];}session.historyStatus='';updateDemo(key);},demoMode==='history'?3500:1000);}
function sendDemo(){const session=activeDemo();const text=$('#chat-draft').value.trim();if(!text||session.busy||!session.loaded)return;const key=demoActive,mode=demoMode;const message={role:'user',text,status:'正在发送…'};session.messages.push(message);session.draft='';session.busy=true;session.status='消息已显示在本机，正在等待接收确认';renderDemo();$('.chat-reading').scrollTop=$('.chat-reading').scrollHeight;later(()=>{message.status='已接收';session.status=mode==='queue'?'已接收，等待处理；请勿重复发送':'正在核对任务与学生记录…';updateDemo(key);},450);later(()=>{session.busy=false;session.status='仅演示，不发送真实请求';const operationId='DEMO-'+String(++localSequence).padStart(4,'0');session.messages.push(key==='follow'?{role:'assistant',text:'已重新核对演示任务：当前仍未记录结果。上次沟通约定不能证明已补交。请先确认实际补交情况，再决定是否更新；本次没有写入。'}:key==='discussion'?{role:'assistant',text:'我们保留先独立思考再分组交流的方案。请补充课文，接着才能确定具体问题与时间安排。'}:{role:'assistant',text:key==='follow'?'已重新读取演示任务。当前结果仍未记录；上次沟通约定不等于已完成。请先核实补交情况，再确认是否更新。':'已核对演示任务与两名参与学生，请确认下面的修改。',phase:'preview',operationId,mode});updateDemo(key);},mode==='queue'?4000:1400);}
function operateDemo(action,index){const key=demoActive,session=activeDemo(),message=session.messages[index];if(action==='cancel'){message.phase='cancelled';renderDemo();return;}if(action==='refresh'){message.phase='cancelled';message.text='最新演示记录显示小周已完成；原批次作废。请核对小林情况后重新提出具体修改。';renderDemo();return;}if(action==='reconcile'){message.phase='checking';renderDemo();later(()=>{message.phase='done';session.busy=false;session.status='已按原编号查到模拟回执，没有重复提交';updateDemo(key);},1200);return;}if(action==='confirm'&&message.phase==='preview'){if(message.mode==='conflict'){message.phase='conflict';renderDemo();return;}message.phase='executing';session.busy=true;session.status='正在提交，请勿重复操作';renderDemo();later(()=>{message.phase=message.mode==='unknown'?'unknown':'done';session.busy=false;session.status=message.mode==='unknown'?'提交结果待核对，请先查询原操作':'已核对模拟回执';updateDemo(key);},1000);}}
function initDemo(){const reading=$('.chat-reading');reading.id='demo-reading';reading.setAttribute('aria-label','当前会话消息');const header=document.createElement('header');header.className='conversation-heading';header.innerHTML='<h2 id="demo-session-title"></h2><p id="demo-history-status" role="status" hidden></p>';reading.before(header);$('.composer>div>span').id='demo-composer-status';$('#demo-composer-status').setAttribute('role','status');$('#demo-composer-status').setAttribute('aria-live','polite');$('#chat-draft').oninput=e=>activeDemo().draft=e.target.value;$('#demo-mode').onchange=e=>{demoMode=e.target.value;toast('演示条件已切换，下次发送或切换会话时生效。');};$('.conversation-list').id='demo-conversations';$('.new-chat').onclick=()=>{const key='new-'+(++localSequence);demoSessions[key]={title:'新对话 · '+localSequence,loaded:true,draft:'',status:'',messages:[{role:'assistant',text:'这是新的演示会话。可以从「记忆与事项」继续旧工作，也可输入消息查看模拟课堂记录流程。'}]};scene('chat');switchDemo(key,false);collapse(true);$('#chat-draft').focus();};renderDemo();}
renderSettings();hydrate();initDemo();
window.addEventListener('beforeunload',()=>{for(const timer of demoTimers)clearTimeout(timer);for(const api of materials.values())api.destroy();});
